// Regenerate src/scenes/index.ts from every scene file, and CATALOG.md from their docs.
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1")), "..");
const dir = path.join(root, "src/scenes");
const names = fs.readdirSync(dir).filter((f) => /^[A-Z]\w*\.tsx$/.test(f)).map((f) => f.replace(/\.tsx$/, "")).sort();
fs.writeFileSync(
  path.join(dir, "index.ts"),
  "// Generated by scripts/gen-registry.mjs; do not edit.\n" +
    names.map((n) => `import ${n} from "./${n}";`).join("\n") +
    `\nimport type { SceneDef } from "./kit";\n\nexport const DEFS: Record<string, SceneDef> = { ${names.join(", ")} };\n` +
    `export const SCENES = Object.fromEntries(Object.entries(DEFS).map(([k, d]) => [k, d.Component]));\n`,
);
const catalog = names.map((n) => {
  const src = fs.readFileSync(path.join(dir, `${n}.tsx`), "utf8");
  const doc = (src.match(/doc:\s*("(?:[^"\\]|\\.)*"|`[^`]*`)/) || [])[1];
  return `## ${n}\n\n${doc ? JSON.parse(doc.startsWith("`") ? JSON.stringify(doc.slice(1, -1)) : doc) : "(no doc)"}\n`;
});
fs.writeFileSync(path.join(root, "CATALOG.md"), "# Scene catalogue\n\nGenerated from each scene's `doc`. See src/scenes/<Name>.tsx `example` for exact props.\n\n" + catalog.join("\n"));
console.log(`${names.length} scenes: ${names.join(", ")}`);
